  console.error(
    `Enrollment ${enrollmentId} terminal needs_review (${reason})`
  );
  // Stryker restore StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral
}

/**
 * Pause active enrollments. Allowed mid-send: clears claim so the in-flight
 * worker's advanceEnrollment ownership check fails (no accidental next step).
 */
export async function pauseCampaignForLead(leadId: string): Promise<void> {
  return pauseCampaignForLeadWithDeps(defaultCampaignDeps(), leadId);
}

export async function pauseCampaignForLeadWithDeps(
  deps: CampaignDeps,
  leadId: string
): Promise<void> {
  const supabase = deps.db();

  const { error } = await supabase
    .from(TABLE.campaignEnrollments)
    .update(
      pauseEnrollmentPayload({
        status: ENROLLMENT_STATUS.paused,
        nowIso: new Date(deps.clock().getTime()).toISOString(),
      })
    )
    .eq(COL.leadId, leadId)
    .eq(COL.status, ENROLLMENT_STATUS.active);

  if (error) {
    // Stryker disable StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral: log-only (no control flow)
    console.error('Failed to pause campaign:', error);
    // Stryker restore StringLiteral,CallExpression,BlockStatement,LogicalOperator,OptionalChaining,ConditionalExpression,EqualityOperator,ObjectLiteral,BooleanLiteral
    // QC r9: do not swallow — inbound ambiguous path must fail closed so the
    // provider retries; callers that want soft-fail wrap in .catch().
    throw new Error(
      `Failed to pause campaign for lead ${leadId}: ${error.message ?? 'unknown'}`
    );
