vi.mock('@/services/suppressions', () => ({
  markLeadOptedOut: (...args: unknown[]) => markLeadOptedOut(...args),
  suppressPhoneForBusiness: (...args: unknown[]) =>
    suppressPhoneForBusiness(...args),
}));

vi.mock('@/services/classification', async () => {
