  it('enrollLeadInCampaign: no_matching_campaign / insert_failed', async () => {
    mockFrom.mockImplementation((table: string) => {
      if (table === 'leads') {
        return chainable({
          data: {
            id: 'L',
            opted_out: false,
            urgency: 'emergency',
