    );
    expect(leadClears).toHaveLength(1);
  });

  it('resolveRecovery absent when lead has no sms_outbound_sid key', async () => {
    const db = makeDb({ leads: {} });
    expect(
      await resolveRecoveryOutcomeWithDeps(
        baseDeps({ dbImpl: db }),
        db as never,
        'L'
      )
    ).toBe('absent');
  });
});

