          next_send_at: null,
          claimed_at: new Date(now.getTime() - CLAIM_STALE_MS - 1).toISOString(),
        },
        now
      )
    ).toBe(true);
  });

  it('selectCampaignForUrgency falls back to Standard when urgency unknown', () => {
    expect(selectCampaignForUrgency(CAMPAIGNS, 'low')).toBe(CAMPAIGNS[2]);
  });
});

